import { existsSync, readFileSync, statSync } from 'node:fs'

/**
 * Load the backup passphrase — WITHOUT ever creating or modifying the key file.
 *
 * `~/.decoricks/backup.key` is created ONCE, by hand, before the first backup,
 * and is then never regenerated by anything. Every `.enc` archive ever taken is
 * only decryptable with this exact key: regenerating (or overwriting) it makes
 * ALL older backups unreadable forever. So no script here may open the file for
 * writing, redirect into it, or "auto-generate" a missing key — a missing key
 * file is a hard refusal, never something we quietly fix by creating one.
 *
 * Refusals enforced before a single byte is read:
 *   - the file does not exist (or is not a regular file);
 *   - the file is empty (or only whitespace) — a corrupt/truncated key would
 *     "work" for encryption and silently break future restores;
 *   - the file is GROUP- or WORLD-readable (any 0o044 bit) — the key protecting
 *     every production backup must be 0600, owner-only.
 *
 * POSIX only: `stat.mode` permission bits are not meaningful on Windows (NTFS
 * ACLs are), where the check is skipped rather than guessed. The operator reads
 * the file; nothing in this repo writes it.
 */

export const BACKUP_KEY_FILE_ENV = 'DECORICKS_BACKUP_KEY_FILE'
export const BACKUP_KEY_INLINE_ENV = 'DECORICKS_BACKUP_KEY'

const GROUP_OR_WORLD_READABLE = 0o044

export const readBackupPassphrase = (opts: { env?: Record<string, string | undefined> } = {}): string => {
  const env = opts.env ?? process.env
  const file = env[BACKUP_KEY_FILE_ENV]

  if (file) {
    if (!existsSync(file)) {
      throw new Error(
        `Refusing to continue: the backup key file "${file}" does not exist.\n` +
          'No script may create it — regenerating the key makes ALL older backups unreadable.\n' +
          'The key file is created ONCE, by hand, and then never regenerated.\n' +
          'See docs/BACKUP_RECOVERY.md.'
      )
    }
    const st = statSync(file)
    if (!st.isFile()) {
      throw new Error(`Refusing to continue: backup key path "${file}" is not a regular file.`)
    }
    const readableBits = st.mode & GROUP_OR_WORLD_READABLE
    if (readableBits !== 0) {
      throw new Error(
        `Refusing to continue: the backup key file "${file}" is group/world-readable ` +
          `(mode ${(st.mode & 0o777).toString(8)}). Protect it with: chmod 600 "${file}"`
      )
    }
    const passphrase = readFileSync(file, 'utf8').trim()
    if (passphrase === '') {
      throw new Error(
        `Refusing to continue: the backup key file "${file}" is empty. An empty passphrase ` +
          'would encrypt new backups under a blank key and break future restores. ' +
          'Restore the original key from wherever it is archived; never regenerate it.'
      )
    }
    return passphrase
  }

  const inline = env[BACKUP_KEY_INLINE_ENV]
  if (inline && inline.trim() !== '') return inline.trim()

  throw new Error(
    `No backup passphrase. Set ${BACKUP_KEY_FILE_ENV} (preferred: a 0600 file OUTSIDE the repo, ` +
      `created once by hand) or ${BACKUP_KEY_INLINE_ENV} (discouraged). The key is never read ` +
      'from the repository and no script will ever create or overwrite it — regenerating it ' +
      'makes every older backup unreadable forever.'
  )
}
